  const jobs = raw.jobs || raw.startups || raw.results || [];
  return jobs.map(job => ({
    json: {
      job_title: (job.title || job.jobTitle || '').trim(),
      company: job.startup_name || (job.startup && job.startup.name) || job.company || '',
      job_url: job.absolute_url || job.url || 'https://wellfound.com/jobs',
      source: 'Wellfound',
      location_text: Array.isArray(job.location_names) ? job.location_names.join(', ') : (job.location || 'Remote'),
