const searchKeywords = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote',
  'work from anywhere', 'remote data analyst', 'remote data scientist',
  'remote ai marketing', 'remote marketing analyst', 'remote growth analyst',
  'remote bi analyst', 'remote automation', 'remote ai workflow',
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'growth analyst', 'ai marketing', 'automation specialist',
  'ai workflow', 'performance marketing', 'martech analyst', 'analytics engineer',
  'marketing data', 'growth marketing', 'digital analytics', 'product analytics',
  'revenue operations', 'revops', 'crm analyst', 'attribution analyst',
  'marketing operations', 'paid media analyst', 'creative strategist'
];

return $input.all().filter(item => {
  if (!item.json.job_title && !item.json.description) return false;
  const text = `${item.json.job_title} ${item.json.description} ${item.json.tags}`.toLowerCase();
  return searchKeywords.some(kw => text.includes(kw));
});

// $input = existing rows from Google Sheets
// Use $('Keyword Pre-Filter').all() to get new jobs
const existingRows = $input.all();
const newJobs = $('Keyword Pre-Filter').all();

const existingUrls = new Set(
  existingRows.map(r => (r.json.job_url || '').trim()).filter(Boolean)
);
const existingKeys = new Set(
  existingRows
    .filter(r => r.json.company && r.json.job_title)
    .map(r => `${(r.json.company || '').toLowerCase().trim()}::${(r.json.job_title || '').toLowerCase().trim()}`)
);

return newJobs.filter(item => {
  const url = (item.json.job_url || '').trim();
  if (!url) return false;
  if (existingUrls.has(url)) return false;
  const key = `${(item.json.company || '').toLowerCase().trim()}::${(item.json.job_title || '').toLowerCase().trim()}`;
  if (existingKeys.has(key)) return false;
  return true;
});

return $input.all().map(item => {
  const response = item.json;
  const jobData = $('Taiwan Hard Filter').all().find(j => {
    // Try to match by index or job_id
    return true; // Will process sequentially via Split in Batches
  });

  // Extract the AI response from OpenAI output
  let aiResult = {};
  try {
    const content = response?.choices?.[0]?.message?.content || '{}';
    aiResult = JSON.parse(content);
  } catch(e) {
    aiResult = {
      taiwan_eligible: 'unclear',
      reason: 'Could not parse AI response',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      decision: 'manual_check'
    };
  }

  // The input item to THIS node should already carry job data
  // because the Split in Batches + AI check processes one job at a time
  // We need to re-merge the original job data with AI results
  // The job data was the INPUT to the AI check node
  const originalJob = $('Split in Batches').item?.json || {};

  return {
    json: {
      ...originalJob,
      ai_taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
      ai_reason: aiResult.reason || '',
      ai_location_risk: aiResult.location_risk || 'medium',
      ai_timezone_risk: aiResult.timezone_risk || 'medium',
      ai_contractor_possible: aiResult.contractor_possible || 'unclear',
      ai_decision: aiResult.decision || 'manual_check'
    }
  };
});

// This node merges the AI eligibility result back with the original job data
// The AI check HTTP node returns the OpenAI response
// We need to pair it with the original job that was sent

// In n8n, when Split in Batches feeds into AI check, each item is processed
// The input item to AI check carries the job json, the output carries the OpenAI response
// We use $input.item to get current item and merge with the previous node's input

return $input.all().map((item, idx) => {
  let aiResult = {};
  try {
    const content = item.json?.choices?.[0]?.message?.content || '{}';
    aiResult = JSON.parse(content);
  } catch(e) {
    aiResult = {
      taiwan_eligible: 'unclear',
      reason: 'parse_error',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      decision: 'manual_check'
    };
  }

  // Get the original job from the node that fed into the HTTP request
  // n8n passes the original item context through
  const originalItem = $('Split in Batches').all()[idx] || { json: {} };

  return {
    json: {
      ...originalItem.json,
      ai_taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
      ai_reason: aiResult.reason || '',
      ai_location_risk: aiResult.location_risk || 'medium',
      ai_timezone_risk: aiResult.timezone_risk || 'medium',
      ai_contractor_possible: aiResult.contractor_possible || 'unclear',
      ai_decision: aiResult.decision || 'manual_check'
    }
  };
});

const asyncKeywords = [
  'async', 'asynchronous', 'flexible hours', 'flexible schedule',
  'distributed team', 'remote first', 'remote-first', 'low meeting',
  'work across time zones', 'no mandatory meetings', 'written communication',
  'self-directed', 'independent work', 'autonomous', 'no overlap required'
];

const syncRejectKeywords = [
  'strict 9 to 5', '9-5 hours', 'fixed us hours', 'fixed est hours',
  'fixed pst hours', 'fixed cet hours', 'daily live calls required',
  'must overlap full business day', 'required core hours',
  'mandatory daily standup', 'fixed working hours'
];

const primaryRoles = [
  'data analyst', 'data scientist', 'junior data scientist',
  'business intelligence', 'bi analyst', 'marketing analyst',
  'performance marketing analyst', 'growth analyst', 'ai marketing',
  'ai automation', 'automation specialist', 'ai workflow',
  'martech analyst', 'marketing data', 'analytics engineer',
  'creative strategist'
];

const adjacentRoles = [
  'product analyst', 'operations analyst', 'revenue operations', 'revops',
  'digital marketing', 'growth marketing', 'customer analytics',
  'crm analyst', 'attribution', 'paid media', 'seo analyst'
];

return $input.all().map(item => {
  const job = { ...item.json };
  const text = `${job.description || ''} ${job.tags || ''} ${job.location_text || ''} ${job.job_title || ''}`.toLowerCase();

  // Sync rejection check
  const isSync = syncRejectKeywords.some(k => text.includes(k));
  if (isSync) {
    job.async_level = 'sync';
    job.reject_reason = 'sync_hours';
    job.score = 0;
    return { json: job };
  }

  // Async level
  const asyncHits = asyncKeywords.filter(k => text.includes(k)).length;
  if (asyncHits >= 3) job.async_level = 'high';
  else if (asyncHits >= 1) job.async_level = 'medium';
  else job.async_level = 'low';

  // Role fit
  const titleLow = (job.job_title || '').toLowerCase();
  const isPrimary = primaryRoles.some(r => titleLow.includes(r) || text.includes(r));
  const isAdjacent = !isPrimary && adjacentRoles.some(r => titleLow.includes(r));
  if (isPrimary) job.role_category = 'primary';
  else if (isAdjacent) job.role_category = 'adjacent';
  else job.role_category = 'other';

  // --- SCORING ---
  let score = 0;

  // Taiwan eligibility (0-40 pts)
  const eligible = job.ai_taiwan_eligible || 'unclear';
  const locRisk = job.ai_location_risk || 'medium';
  const twKeywords = ['worldwide remote', 'work from anywhere', 'global remote', 'anywhere', 'contractor'];
  const clearlyGlobal = twKeywords.some(k => text.includes(k));

  if (eligible === 'yes' && locRisk === 'low') score += 40;
  else if (eligible === 'yes') score += 35;
  else if (text.includes('apac')) score += 30;
  else if (eligible === 'unclear' && locRisk !== 'high') score += 20;
  else score += 0;

  if (clearlyGlobal && score < 40) score = Math.max(score, 30);

  // Async fit (0-25 pts)
  if (job.async_level === 'high') score += 25;
  else if (job.async_level === 'medium') score += 20;
  else if (text.includes('distributed team')) score += 15;
  else if (text.includes('remote first') || text.includes('remote-first')) score += 10;
  else score += 5;

  // Role fit (0-25 pts)
  if (job.role_category === 'primary') score += 25;
  else if (job.role_category === 'adjacent') score += 15;
  else score += 0;

  // Salary (0-25 pts)
  const salText = (job.salary || '').replace(/,/g, '');
  const salNums = salText.match(/(\d+)/g);
  if (salNums && salNums.length > 0) {
    const salNum = parseInt(salNums[0]);
    // Annual salary
    if (salNum >= 60000) score += 25;
    else if (salNum >= 36000) score += 15;
    // Monthly salary
    else if (salNum >= 5000) score += 25;
    else if (salNum >= 3000) score += 15;
    else score += 10;
  }

  job.score = score;

  // Build why_good_fit summary
  const reasons = [];
  if (eligible === 'yes') reasons.push('Taiwan eligible');
  if (clearlyGlobal) reasons.push('globally remote');
  if (job.async_level === 'high' || job.async_level === 'medium') reasons.push(`${job.async_level} async`);
  if (job.role_category === 'primary') reasons.push('direct role match');
  if (job.salary) reasons.push('salary listed');
  job.why_good_fit = reasons.join(', ') || 'Potential fit - review manually';

  return { json: job };
});

return $input.all().map(item => {
  const coverLetterContent = item.json?.choices?.[0]?.message?.content || '';
  // Pair with the original job from High Score Check
  const originalJob = $('High Score Check').item?.json || {};
  return {
    json: {
      ...originalJob,
      cover_letter: coverLetterContent,
      cover_letter_generated: true
    }
  };
});

const today = new Date().toISOString().split('T')[0];
const allItems = $input.all().map(i => i.json);

// Separate filtered (have score) and rejected (no score field from Rejected sheet)
const filtered = allItems.filter(j => j.score !== undefined && j.date_found === today).sort((a, b) => (b.score || 0) - (a.score || 0));
const rejected = allItems.filter(j => j.date_rejected === today || (j.reason && !j.score));

// Count rejection reasons
const rejectionCounts = {
  us_only: 0,
  eu_only: 0,
  hybrid: 0,
  timezone: 0,
  score_below_70: 0,
  other: 0
};
rejected.forEach(r => {
  const reason = (r.reason || '').toLowerCase();
  if (reason.includes('us only') || reason.includes('us_only')) rejectionCounts.us_only++;
  else if (reason.includes('eu only') || reason.includes('eu_only') || reason.includes('europe')) rejectionCounts.eu_only++;
  else if (reason.includes('hybrid')) rejectionCounts.hybrid++;
  else if (reason.includes('timezone') || reason.includes('sync_hours')) rejectionCounts.timezone++;
  else if (reason.includes('score')) rejectionCounts.score_below_70++;
  else rejectionCounts.other++;
});

// Top jobs (score >= 70)
const topJobs = filtered.filter(j => (j.score || 0) >= 70).slice(0, 10);
// Instant alert jobs (score >= 85)
const alertJobs = filtered.filter(j => (j.score || 0) >= 85);
// Manual check jobs (taiwan unclear but high score)
const manualCheck = filtered.filter(j => j.taiwan_eligible === 'unclear' && (j.score || 0) >= 75);

let emailBody = `<h2>Daily Taiwan Eligible Async Remote Jobs - ${today}</h2>`;

if (alertJobs.length > 0) {
  emailBody += `<p><strong>🔥 HIGH PRIORITY - ${alertJobs.length} job(s) scoring 85+</strong></p>`;
}

emailBody += `<p>Found <strong>${topJobs.length}</strong> qualifying jobs today (score ≥ 70).</p>`;

if (topJobs.length === 0) {
  emailBody += `<p>No qualifying jobs found today. Check back tomorrow.</p>`;
} else {
  emailBody += `<h3>Top Jobs Today:</h3>`;

  topJobs.forEach((job, i) => {
    const scoreEmoji = (job.score || 0) >= 85 ? '🔥' : (job.score || 0) >= 75 ? '⭐' : '✅';
    emailBody += `
      <div style="border:1px solid #ddd; padding:12px; margin:8px 0; border-radius:6px;">
        <h4>${i + 1}. ${scoreEmoji} ${job.job_title || 'Unknown Title'}</h4>
        <p><strong>Company:</strong> ${job.company || 'N/A'}</p>
        <p><strong>Score:</strong> ${job.score || 0}/100</p>
        <p><strong>Taiwan Eligible:</strong> ${job.taiwan_eligible || 'unclear'}</p>
        <p><strong>Reason:</strong> ${job.taiwan_reason || 'N/A'}</p>
        <p><strong>Async Level:</strong> ${job.async_level || 'unknown'}</p>
        <p><strong>Timezone Risk:</strong> ${job.timezone_risk || 'unknown'}</p>
        <p><strong>Location Risk:</strong> ${job.location_risk || 'unknown'}</p>
        <p><strong>Salary:</strong> ${job.salary || 'Not listed'}</p>
        <p><strong>Why it fits Jerry:</strong> ${job.why_good_fit || 'N/A'}</p>
        <p><a href="${job.job_url || '#'}" style="background:#0066cc;color:white;padding:6px 12px;text-decoration:none;border-radius:4px;">Apply Now</a></p>
      </div>
    `;
  });
}

if (manualCheck.length > 0) {
  emailBody += `<h3>🔍 Manual Check Required (${manualCheck.length} jobs):</h3>`;
  manualCheck.forEach(job => {
    emailBody += `<p>• <a href="${job.job_url}">${job.job_title} @ ${job.company}</a> — Score: ${job.score}, Taiwan: unclear</p>`;
  });
}

emailBody += `
  <h3>Rejection Summary:</h3>
  <ul>
    <li>US Only: ${rejectionCounts.us_only}</li>
    <li>EU Only: ${rejectionCounts.eu_only}</li>
    <li>Hybrid/Onsite: ${rejectionCounts.hybrid}</li>
    <li>Timezone Risk (sync hours): ${rejectionCounts.timezone}</li>
    <li>Score Below 70: ${rejectionCounts.score_below_70}</li>
    <li>Other: ${rejectionCounts.other}</li>
  </ul>
  <p style="color:#888;font-size:12px;">Generated by Daily Taiwan Eligible Async Remote Job Hunter • ${new Date().toLocaleString('en-US', {timeZone: 'Asia/Taipei'})} Taipei Time</p>
`;

return [{ json: { emailBody, topJobCount: topJobs.length, alertJobCount: alertJobs.length, today } }];
